#:sdk Microsoft.NET.Sdk.Web #:package WolverineFx@3.0.0 #:package System.Transactions@8.0.0 #:property TargetFramework=net11.0 #:property Nullable=enable  using Wolverine; using System.Transactions;  // XA事务中间件 public static class XATransactionMiddleware {     public static async Task BeforeAsync(IMessageContext context, ILogger logger)     {         if (context.Envelope?.Message is not IXATransactional)             return;          var scope = new TransactionScope(             TransactionScopeOption.Required,             new TransactionOptions             {                 IsolationLevel = IsolationLevel.ReadCommitted,                 Timeout = TransactionManager.DefaultTimeout             },             TransactionScopeAsyncFlowOption.Enabled);          logger.LogInformation("XA事务开始: {MessageType}", context.Envelope.Message.GetType().Name);         context.Items["XATransactionScope"] = scope;     }      public static async Task AfterAsync(IMessageContext context, ILogger logger)     {         if (context.Items.TryGetValue("XATransactionScope", out var obj) && obj is TransactionScope scope)         {             scope.Complete();             logger.LogInformation("XA事务提交: {MessageType}", context.Envelope.Message.GetType().Name);             scope.Dispose();         }     }      public static async Task OnErrorAsync(IMessageContext context, Exception ex, ILogger logger)     {         if (context.Items.TryGetValue("XATransactionScope", out var obj) && obj is TransactionScope scope)         {             logger.LogError(ex, "XA事务回滚: {MessageType}", context.Envelope.Message.GetType().Name);             scope.Dispose();         }     } }  // DI扩展 public static class WolverineDependencyInjectionExtensions {     public static WolverineOptions UseXATransactionSupport(this WolverineOptions options)     {         options.Policies.AddMiddleware<XATransactionMiddleware>();         return options;     } }  // 使用示例 public class OrderService {     private readonly IMessageBus _bus;      public OrderService(IMessageBus bus)     {         _bus = bus;     }      public async Task CreateOrderAsync(CreateOrderCommand command)     {         // 此命令将自动参与XA事务         await _bus.SendAsync(command);     } }
